<script setup lang="ts">
import { onMounted, reactive, ref, computed } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { supabase } from '../lib/supabase'
import type { Attribute, Character } from '../lib/types'
const route = useRoute(); const router = useRouter(); const saving = ref(false); const loading = ref(false); const error = ref(''); const isEdit = computed(() => Boolean(route.params.id)); const attributes = ref<Attribute[]>([])
const form = reactive({ name: '', species: '', role: '', level: '', health: '', max_health: '', experience: '', abilities: '', biography: '' }); const fieldErrors = reactive<Record<string, string>>({})
function setFields(character: Character) { form.name = character.name; form.species = character.species || ''; form.role = character.role || ''; form.level = character.level === null ? '' : String(character.level); form.health = character.health === null ? '' : String(character.health); form.max_health = character.max_health === null ? '' : String(character.max_health); form.experience = character.experience === null ? '' : String(character.experience); form.abilities = character.abilities || ''; form.biography = character.biography || '' }
async function load() { if (!isEdit.value) return; loading.value = true; const id = String(route.params.id); const [{ data: character, error: characterError }, { data: stats }] = await Promise.all([supabase.from('characters').select('*').eq('id', id).maybeSingle(), supabase.from('character_attributes').select('*').eq('character_id', id).order('position')]); if (characterError || !character) error.value = 'That character could not be loaded.'; else { setFields(character); attributes.value = stats || [] }; loading.value = false }
function validate() { Object.keys(fieldErrors).forEach(key => delete fieldErrors[key]); if (!form.name.trim()) fieldErrors.name = 'Name is required.'; if (form.name.length > 100) fieldErrors.name = 'Name must be 100 characters or fewer.'; for (const key of ['species','role'] as const) if (form[key].length > 100) fieldErrors[key] = 'Must be 100 characters or fewer.'; for (const key of ['abilities','biography'] as const) if (form[key].length > 5000) fieldErrors[key] = 'Must be 5,000 characters or fewer.'; for (const key of ['level','max_health','experience'] as const) if (form[key] && (!/^\d+$/.test(form[key]) || Number(form[key]) < 0 || (key === 'level' && Number(form[key]) > 10000))) fieldErrors[key] = key === 'level' ? 'Use a whole number from 0 to 10,000.' : 'Use a whole number of 0 or more.'
  // manual change: current health may be negative (a downed character), as v1/v2 and the database allow
  if (form.health && (!/^-?\d+$/.test(form.health) || Math.abs(Number(form.health)) > 1000000)) fieldErrors.health = 'Use a whole number from -1,000,000 to 1,000,000.'
  return !Object.keys(fieldErrors).length }
function value(key: 'level'|'health'|'max_health'|'experience') { return form[key] === '' ? null : Number(form[key]) }
function friendly(message: string) { if (message.startsWith('PLAN_LIMIT_REACHED:')) return message.split(':').slice(1).join(':').trim(); if (message.includes('duplicate') || message.includes('unique')) return 'A character with those details already exists.'; if (message.includes('network')) return 'Network connection failed. Try again.'; return 'The character could not be saved. Check the form and try again.' }
async function save() { error.value = ''; if (!validate()) return; saving.value = true; const payload = { name: form.name.trim(), species: form.species || null, role: form.role || null, level: value('level'), health: value('health'), max_health: value('max_health'), experience: value('experience'), abilities: form.abilities || null, biography: form.biography || null }; let characterId = String(route.params.id); const result = isEdit.value ? await supabase.from('characters').update(payload).eq('id', characterId).select().maybeSingle() : await supabase.from('characters').insert(payload).select().maybeSingle(); if (result.error || !result.data) { error.value = friendly(result.error?.message || ''); saving.value = false; return }; characterId = result.data.id; const filled = attributes.value.filter(attribute => attribute.name.trim() && attribute.value.trim()).map((attribute, index) => ({ character_id: characterId, name: attribute.name.trim(), value: attribute.value.trim(), position: index })); if (isEdit.value) { const { error: deleteError } = await supabase.from('character_attributes').delete().eq('character_id', characterId); if (deleteError) { error.value = 'Character saved, but attributes could not be updated.'; saving.value = false; return } } if (filled.length) { const { error: attributeError } = await supabase.from('character_attributes').insert(filled); if (attributeError) { error.value = 'Character saved, but attributes could not be saved.'; saving.value = false; return } } saving.value = false; await router.push(`/characters/${characterId}?tab=overview`) }
function addAttribute() { attributes.value.push({ name: '', value: '', position: attributes.value.length }) }
function removeAttribute(index: number) { attributes.value.splice(index, 1) }
function useDefaults() { attributes.value = ['Strength','Dexterity','Constitution','Intelligence','Wisdom','Charisma'].map((name, position) => ({ name, value: '10', position })) }
// manual change: new characters start with the d&d defaults; the user can change, remove or add before saving
if (!isEdit.value) useDefaults()
onMounted(() => { void load() })
</script>
<template><section class="page form-page"><button class="back-link" @click="router.push('/characters')">← Back to characters</button><div class="eyebrow">{{ isEdit ? 'Edit entry' : 'New entry' }}</div><h2>{{ isEdit ? 'Shape your character' : 'Create a character' }}</h2><p class="muted">Only a name is required. The rest of their story can unfold over time.</p><div v-if="loading" class="empty"><p class="muted">Loading character…</p></div><form v-else class="character-form" @submit.prevent="save"><div class="form-section"><h3>Identity</h3><div class="form-grid"><label class="wide">Name *<input v-model="form.name" maxlength="100" placeholder="A name worthy of song" required /><small v-if="fieldErrors.name" class="field-error">{{ fieldErrors.name }}</small></label><label>Species<input v-model="form.species" maxlength="100" placeholder="Moon Elf" /><small v-if="fieldErrors.species" class="field-error">{{ fieldErrors.species }}</small></label><label>Role<input v-model="form.role" maxlength="100" placeholder="Spellblade" /><small v-if="fieldErrors.role" class="field-error">{{ fieldErrors.role }}</small></label></div></div><div class="form-section"><h3>Core stats</h3><div class="form-grid"><label>Level<input v-model="form.level" inputmode="numeric" placeholder="0" /><small v-if="fieldErrors.level" class="field-error">{{ fieldErrors.level }}</small></label><label>Health<input v-model="form.health" placeholder="0" /><small v-if="fieldErrors.health" class="field-error">{{ fieldErrors.health }}</small></label><label>Max health<input v-model="form.max_health" inputmode="numeric" placeholder="0" /><small v-if="fieldErrors.max_health" class="field-error">{{ fieldErrors.max_health }}</small></label><label>Experience<input v-model="form.experience" inputmode="numeric" placeholder="0" /><small v-if="fieldErrors.experience" class="field-error">{{ fieldErrors.experience }}</small></label></div></div><div class="form-section"><h3>Custom attributes</h3><div v-for="(attribute, index) in attributes" :key="attribute.id || index" class="attribute-row"><input v-model="attribute.name" maxlength="50" placeholder="Attribute name" /><input v-model="attribute.value" maxlength="100" placeholder="Value" /><button type="button" @click="removeAttribute(index)">×</button></div><div class="attribute-actions"><button type="button" class="small-button" @click="addAttribute">＋ Add attribute</button><button type="button" class="small-button gold-button" @click="useDefaults">Use D&D defaults</button></div></div><div class="form-section"><h3>Story</h3><label>Powers & abilities<textarea v-model="form.abilities" maxlength="5000" rows="3" placeholder="What can they do that others cannot?"></textarea><small v-if="fieldErrors.abilities" class="field-error">{{ fieldErrors.abilities }}</small></label><label>Backstory<textarea v-model="form.biography" maxlength="5000" rows="4" placeholder="Every legend begins somewhere…"></textarea><small v-if="fieldErrors.biography" class="field-error">{{ fieldErrors.biography }}</small></label></div><p v-if="error" class="form-error">{{ error }}</p><button class="primary" type="submit" :disabled="saving">{{ saving ? 'Saving…' : isEdit ? 'Save changes' : 'Add to the chronicles' }}</button></form></section></template>
